package main

import (
	"fmt"
	"sort"
)

func mergeIntervals(intervals [][2]int) [][2]int {
	sort.Slice(intervals, func(i, j int) bool {
		return intervals[i][0] < intervals[j][0]
	})
	merged := [][2]int{}
	for _, interval := range intervals {
		last := len(merged) - 1
		if last < 0 || merged[last][1] < interval[0] {
			merged = append(merged, interval)
		} else if interval[1] > merged[last][1] {
			merged[last][1] = interval[1]
		}
	}
	return merged
}

func main() {
	var n int
	fmt.Scan(&n)
	intervals := make([][2]int, n)
	for i := range intervals {
		fmt.Scan(&intervals[i][0], &intervals[i][1])
	}
	for _, interval := range mergeIntervals(intervals) {
		fmt.Println(interval[0], interval[1])
	}
}

